INSERT INTO intake (body, author, theme) VALUES
    ('A man of character finds a special attractiveness in difficulty.', 'Charles de Gaulle', 'adversity'),
    ('Difficulties are meant to rouse, not discourage. The human spirit is to grow strong by conflict.', 'William Ellery Channing', 'adversity'),
    ('If you can''t fly then run, if you can''t run then walk, if you can''t walk then crawl, but whatever you do you have to keep moving forward.', 'Martin Luther King Jr.', 'adversity'),
    ('The ultimate measure of a man is not where he stands in moments of comfort and convenience, but where he stands at times of challenge and controversy.', 'Martin Luther King Jr.', 'adversity'),
    ('Darkness cannot drive out darkness; only light can do that.', 'Martin Luther King Jr.', 'adversity'),
    ('Faith is taking the first step even when you don''t see the whole staircase.', 'Martin Luther King Jr.', 'adversity'),
    ('There is no education like adversity.', 'Benjamin Disraeli', 'adversity'),
    ('Those things that hurt, instruct.', 'Benjamin Franklin', 'adversity'),
    ('Adversity is like a strong wind. It tears away from us all but the things that cannot be torn, so that we see ourselves as we really are.', 'Arthur Golden', 'adversity'),
    ('What makes the desert beautiful is that somewhere it hides a well.', 'Antoine de Saint-Exupery', 'adversity');
